def magic_square_test(square):
  # Calculate the sum of the first row to check if all rows have the same sum
  row_sum = sum(square[0])
  
  # Check if all rows have the same sum
  for row in square:
    if sum(row) != row_sum:
      return False

  # Calculate the sum of the first column to check if all columns have the same sum
  col_sum = sum(square[i][0] for i in range(len(square)))
  
  # Check if all columns have the same sum
  for j in range(len(square)):
    if sum(square[j]) != col_sum:
      return False

  # Calculate the sum of the main diagonal to check if all diagonals have the same sum
  diag_sum = sum(square[i][i] for i in range(len(square)))
  
  # Check if all diagonals have the same sum
  if sum(square[i][len(square)-1-i] for i in range(len(square))) != diag_sum:
    return False

  # If all checks pass, the square is a magic square
  return True

