def shell_sort(arr):
  size = len(arr)
  gap = size // 2

  while gap > 0:
    for i in range(gap, size):
      temp = arr[i]
      j = i - gap
      while j >= 0 and arr[j] > temp:
        arr[j + gap] = arr[j]
        j -= gap
      arr[j + gap] = temp
    gap //= 2

