def max_product(arr,n): 
  # Initialize the dp array with 1s
  dp = [1]*n
  
  # Iterate over each element in the array
  for i in range(1,n):
      # Find the maximum product ending at arr[i]
      for j in range(i):
          if arr[j] < arr[i]:
              dp[i] = max(dp[i], dp[j]*arr[i])
      
  # Return the maximum value in the dp array
  return max(dp)

def max_profit(prices, k):
  if not prices or k <= 0:
    return 0

  dp = [[0] * (k + 1) for _ in range(len(prices))]

  for i in range(1, len(prices)):
    for j in range(1, k + 1):
      # Buy the stock at price[i]
      buy = dp[i - 1][j] - prices[i]
      # Sell the stock at price[i]
      sell = dp[i - 1][j - 1] + prices[i]
      # Maximize the profit
      dp[i][j] = max(buy, sell)

  return dp[-1][-1]

